scripts.check:ui-stubs:
node --input-type=module <<'EOF'
import { readdirSync, readFileSync } from 'fs';
import { join, relative } from 'path';
const STUB_RE = /^export\s+(\*|\{[^}]+\})\s+from\s+["']@workspace\/ui["'];?$/;
const dirs = ['artifacts/hrp-tracker/src/components/ui', 'artifacts/mockup-sandbox/src/components/ui'];
let failed = false;
for (const dir of dirs) {
  let files;
  try { files = readdirSync(dir); } catch { continue; }
  for (const f of files) {
    if (!f.endsWith('.tsx') && !f.endsWith('.ts')) continue;
    const content = readFileSync(join(dir, f), 'utf8').trim();
    if (!STUB_RE.test(content)) {
      console.error(`ERROR: ${relative('.', join(dir, f))} is not a re-export stub.`);
      console.error(`  Expected a single: export * from "@workspace/ui"; (or named re-export)`);
      console.error(`  Got:      ${content.slice(0, 120)}${content.length > 120 ? '…' : ''}`);
      console.error(`  Fix: move component logic to lib/ui/src/components/ instead.`);
      failed = true;
    }
  }
}
if (failed) process.exit(1);
console.log('All artifact ui/ stubs are valid.');
EOF
